def count_complete_vowel_substrings(word):
    vowels=set('aeiou');answer=0
    for left in range(len(word)):
        seen=set()
        for right in range(left,len(word)):
            if word[right] not in vowels:break
            seen.add(word[right])
            if len(seen)==5:answer+=1
    return answer

